{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.Mnow_master as WITH inward_data AS ( SELECT SKU_GROUP, MIN(DATE) AS first_inward_date, SUM(OPENING_INVENTORY) AS opening_inventory FROM snitch_db.maplemonk.Mnow_inventory_report WHERE (SKU_GROUP, DATE) IN ( SELECT SKU_GROUP, MIN(DATE) FROM snitch_db.maplemonk.Mnow_inventory_report GROUP BY SKU_GROUP ) GROUP BY SKU_GROUP ), sales_after_inward AS ( SELECT k.SKU_GROUP, i.first_inward_date, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 7, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_7, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 15, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_15, SUM(CASE WHEN k.ORDER_DATE <= DATEADD(DAY, 30, i.first_inward_date) THEN TOTAL_QUANTITY ELSE 0 END) AS sales_day_30 FROM snitch_db.maplemonk.Mnow_fact_item k JOIN inward_data i ON k.SKU_GROUP = i.SKU_GROUP GROUP BY k.SKU_GROUP, i.first_inward_date ), str_data AS ( SELECT s.SKU_GROUP, i.opening_inventory, DIV0(s.sales_day_7, i.opening_inventory) AS STR_DAY_7, DIV0(s.sales_day_15, i.opening_inventory) AS STR_DAY_15, DIV0(s.sales_day_30, i.opening_inventory) AS STR_DAY_30 FROM sales_after_inward s JOIN inward_data i ON s.SKU_GROUP = i.SKU_GROUP ), sku_group_data AS ( SELECT sku_group, order_date, SUM(TOTAL_QUANTITY) AS suborder_quantity, SUM(return_quantity) AS return_quantity, MAX(MRP) AS mrp, SUM(SP) AS SP FROM snitch_db.MAPLEMONK.Mnow_fact_item GROUP BY 1, 2 ), first_order_dates AS ( SELECT sku_group, MIN(order_date) AS first_order_date, MAX(order_date) AS last_order_date, DATEDIFF(\'DAY\', MIN(order_date), CURRENT_DATE) AS days_since_first_order, DATEDIFF(\'DAY\', MAX(order_date), CURRENT_DATE) AS days_since_last_order, DATEDIFF(\'DAY\', MIN(order_date), MAX(order_date)) AS total_days_sold FROM sku_group_data GROUP BY sku_group ), total_sales AS ( SELECT sgd.sku_group, fod.first_order_date, fod.last_order_date, fod.days_since_first_order, fod.days_since_last_order, fod.total_days_sold, MAX(sgd.MRP) AS MRP, DIV0(SUM(sgd.SP), SUM(sgd.suborder_quantity)) AS ASP, SUM(sgd.return_quantity) AS total_returns, SUM(sgd.suborder_quantity) AS total_sales, SUM(CASE WHEN sgd.order_date <= DATEADD(\'DAY\', 30, fod.first_order_date) THEN sgd.suborder_quantity ELSE 0 END) AS sales_first_30_days, SUM(CASE WHEN sgd.order_date <= DATEADD(\'DAY\', 15, fod.first_order_date) THEN sgd.suborder_quantity ELSE 0 END) AS sales_first_15_days, SUM(CASE WHEN sgd.order_date <= DATEADD(\'DAY\', 7, fod.first_order_date) THEN sgd.suborder_quantity ELSE 0 END) AS sales_first_7_days, SUM(CASE WHEN sgd.order_date <= DATEADD(\'DAY\', 90, fod.first_order_date) THEN sgd.suborder_quantity ELSE 0 END) AS sales_first_90_days, SUM(CASE WHEN sgd.order_date <= DATEADD(\'DAY\', 60, fod.first_order_date) THEN sgd.suborder_quantity ELSE 0 END) AS sales_first_60_days, SUM(CASE WHEN CURRENT_DATE - sgd.order_date <= 30 THEN sgd.suborder_quantity ELSE 0 END) AS sales_last_30_days, SUM(CASE WHEN CURRENT_DATE - sgd.order_date <= 15 THEN sgd.suborder_quantity ELSE 0 END) AS sales_last_15_days, SUM(CASE WHEN CURRENT_DATE - sgd.order_date <= 7 THEN sgd.suborder_quantity ELSE 0 END) AS sales_last_7_days, SUM(CASE WHEN CURRENT_DATE - sgd.order_date <= 60 THEN sgd.suborder_quantity ELSE 0 END) AS sales_last_60_days, CASE WHEN fod.total_days_sold = 0 THEN SUM(sgd.suborder_quantity) ELSE SUM(sgd.suborder_quantity) / (fod.total_days_sold + 1) END AS natural_ros FROM sku_group_data sgd INNER JOIN first_order_dates fod ON sgd.sku_group = fod.sku_group GROUP BY sgd.sku_group, fod.first_order_date, fod.last_order_date, fod.days_since_first_order, fod.days_since_last_order, fod.total_days_sold ), enhanced_total_sales AS ( SELECT ts.*, GREATEST( DIV0(ts.sales_first_30_days, 30), DIV0(ts.sales_last_30_days, 30), ts.natural_ros ) AS max_first_30_last_30_natural_ros, DIV0(ts.total_returns, ts.total_sales) * 100 AS average_return_since_first_order, GREATEST( DIV0(ts.sales_last_30_days, 30), ts.natural_ros ) AS final_ros FROM total_sales ts ), PivotTable AS ( SELECT TRIM(UPPER(sku_group)) AS sku_group, GREATEST(SUM(closing_inventory), 0) AS Sellable_Inventory, SUM(CASE WHEN SIZE IN (\'XS\', \'28\') THEN closing_inventory ELSE 0 END) AS XS_units, SUM(CASE WHEN SIZE IN (\'S\', \'30\') THEN closing_inventory ELSE 0 END) AS S_units, SUM(CASE WHEN SIZE IN (\'M\', \'32\') THEN closing_inventory ELSE 0 END) AS M_units, SUM(CASE WHEN SIZE IN (\'L\', \'34\') THEN closing_inventory ELSE 0 END) AS L_units, SUM(CASE WHEN SIZE IN (\'XL\', \'36\') THEN closing_inventory ELSE 0 END) AS XL_units, SUM(CASE WHEN SIZE IN (\'XXL\', \'2XL\', \'38\') THEN closing_inventory ELSE 0 END) AS XXL_units, SUM(CASE WHEN SIZE IN (\'3XL\', \'40\') THEN closing_inventory ELSE 0 END) AS XL3_units, (CASE WHEN SUM(CASE WHEN SIZE = \'S\' THEN closing_inventory ELSE 0 END) > 0 THEN 1 ELSE 0 END) + (CASE WHEN SUM(CASE WHEN SIZE = \'M\' THEN closing_inventory ELSE 0 END) > 0 THEN 1 ELSE 0 END) + (CASE WHEN SUM(CASE WHEN SIZE = \'L\' THEN closing_inventory ELSE 0 END) > 0 THEN 1 ELSE 0 END) + (CASE WHEN SUM(CASE WHEN SIZE = \'XL\' THEN closing_inventory ELSE 0 END) > 0 THEN 1 ELSE 0 END) AS num_size_available FROM snitch_db.maplemonk.Mnow_inventory_report WHERE date = CURRENT_DATE - 1 GROUP BY sku_group ), metafields_data AS ( SELECT DISTINCT TRIM(UPPER(SKU_GROUP)) AS sku_group, TITLE, PRINT_DESIGN, COLLAR_NEW, MATERIAL_NEW, FIT, COLOR, SLEEVE_TYPE, category FROM snitch_db.maplemonk.metafields_data QUALIFY ROW_NUMBER() OVER (PARTITION BY sku_group ORDER BY sku_group) = 1 ), category_pareto AS ( SELECT e.sku_group, m.category, DIV0( SUM(e.total_sales) OVER (PARTITION BY m.category ORDER BY e.total_sales DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), SUM(e.total_sales) OVER (PARTITION BY m.category) ) * 100 AS cumulative_sales_pct, CASE WHEN DIV0( SUM(e.total_sales) OVER (PARTITION BY m.category ORDER BY e.total_sales DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), SUM(e.total_sales) OVER (PARTITION BY m.category) ) * 100 <= 40 THEN \'Top 40%\' WHEN DIV0( SUM(e.total_sales) OVER (PARTITION BY m.category ORDER BY e.total_sales DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), SUM(e.total_sales) OVER (PARTITION BY m.category) ) * 100 <= 80 THEN \'40-80%\' ELSE \'Bottom 20%\' END AS pareto_segment FROM enhanced_total_sales e LEFT JOIN metafields_data m ON e.sku_group = m.sku_group ), fallback_metafields AS ( SELECT SKU_GROUP, CATEGORY, TITLE, MATERIAL_NEW, PRINT_DESIGN, FIT, SLEEVE_TYPE, COLLAR_NEW FROM snitch_db.maplemonk.GS_MP_SKU_META_SHEET1 QUALIFY ROW_NUMBER() OVER(PARTITION BY SKU_GROUP ORDER BY SKU_GROUP) = 1 ), mp_categories AS ( SELECT DISTINCT REGEXP_REPLACE(SKU, \'-[^-]*$\', \'\') AS sku_group, ANY_VALUE(CATEGORY) AS category FROM snitch_db.maplemonk.LOGIC_FINAL_ITEM_MASTER WHERE SKU LIKE \'MP%\' GROUP BY 1 ) SELECT COALESCE(a.sku_group, b.sku_group) AS sku_group, a.first_order_date, a.last_order_date, a.days_since_first_order, a.days_since_last_order, a.total_days_sold, a.MRP, a.ASP, a.total_returns, a.total_sales, a.sales_first_30_days, a.sales_first_15_days, a.sales_first_7_days, a.sales_first_90_days, a.sales_first_60_days, a.sales_last_30_days, a.sales_last_15_days, a.sales_last_7_days, a.sales_last_60_days, a.natural_ros, a.max_first_30_last_30_natural_ros, a.average_return_since_first_order, a.final_ros, d.opening_inventory, d.STR_DAY_7, d.STR_DAY_15, d.STR_DAY_30, b.SELLABLE_INVENTORY, b.XS_UNITS, b.S_UNITS, b.M_UNITS, b.L_UNITS, b.XL_UNITS, b.XXL_UNITS, b.XL3_UNITS, b.num_size_available, CASE WHEN b.num_size_available < 3 AND b.num_size_available > 0 THEN \'Cut Size\' WHEN b.num_size_available >= 3 THEN \'Full Size\' ELSE \'No Stock\' END AS Cute_Size_Flag, DIV0((a.TOTAL_SALES - a.TOTAL_RETURNS), (a.TOTAL_SALES - a.TOTAL_RETURNS + B.SELLABLE_INVENTORY)) * 100 AS Sell_through, DIV0(B.SELLABLE_INVENTORY, (DIV0(a.SALES_LAST_30_DAYS, 30))) AS DOI, COALESCE(m.TITLE, fb.TITLE) AS TITLE, COALESCE(m.PRINT_DESIGN, fb.PRINT_DESIGN) AS PRINT_DESIGN, COALESCE(m.COLLAR_NEW, fb.COLLAR_NEW) AS COLLAR_NEW, COALESCE(m.MATERIAL_NEW, fb.MATERIAL_NEW) AS MATERIAL_NEW, COALESCE(m.FIT, fb.FIT) AS FIT, m.COLOR, COALESCE(m.SLEEVE_TYPE, fb.SLEEVE_TYPE) AS SLEEVE_TYPE, INITCAP(COALESCE(mpc.category, m.category, fb.CATEGORY)) AS category, cp.cumulative_sales_pct, cp.pareto_segment FROM enhanced_total_sales a FULL OUTER JOIN PivotTable b ON a.sku_group = b.sku_group LEFT JOIN str_data d ON COALESCE(a.sku_group, b.sku_group) = d.sku_group LEFT JOIN metafields_data m ON COALESCE(a.sku_group, b.sku_group) = m.sku_group LEFT JOIN category_pareto cp ON COALESCE(a.sku_group, b.sku_group) = cp.sku_group LEFT JOIN mp_categories mpc ON COALESCE(a.sku_group, b.sku_group) = mpc.sku_group LEFT JOIN fallback_metafields fb ON COALESCE(a.sku_group, b.sku_group) = fb.SKU_GROUP ORDER BY a.total_sales DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            